const serverUrl = 'http://minecraft-250712.kodelab.dev:8100';
// Input text
const positionText = $input.first().json.body.position

// Parse coordinates
const regex = /X=([-+]?\d*\.?\d+),?\s*Y=([-+]?\d*\.?\d+),?\s*Z=([-+]?\d*\.?\d+)/i;
const match = positionText.match(regex);

if (match) {
  const playerX = parseFloat(match[1]);
  // const playerY = parseFloat(match[2]);
  const playerZ = parseFloat(match[3]);

  // Configuration
  const world = 'world';
  const mapType = 't';
  const zoom = 0;
  const tileSize = 128;
  const gridSize = 3;

  // Calculate center tile
  const centerTileX = Math.floor(playerX / tileSize);
  const centerTileZ = Math.floor(playerZ / tileSize);
  const offset = Math.floor(gridSize / 2);

  const tiles = [];

  // Generate 3x3 grid of tiles
  for (let x = -offset; x <= offset; x++) {
    for (let z = -offset; z <= offset; z++) {
      const tileX = centerTileX + x;
      const tileZ = centerTileZ + z;
      const tileUrl = `${serverUrl}/tiles/${world}/${mapType}/${zoom}/${tileX}_${tileZ}.png`;

      tiles.push({
        tileX: tileX,
        tileZ: tileZ,
        url: tileUrl
      });
    }
  } // <-- This closing brace was missing!

  return {
    json: {
      playerPosition: { x: playerX, z: playerZ },
      centerTile: { x: centerTileX, z: centerTileZ },
      tiles: tiles,
      totalTiles: tiles.length
    }
  };
} else {
  return {
    json: {
      error: "Could not parse position",
      originalText: positionText
    }
  };
}

