from PIL import Image, ImageDraw, ImageFont
import base64
import io

def stitch_minecraft_tiles():
    try:
        tile_images = {}
        paired_items = []

        # Debug: Print all available coordinates first
        print("=== DEBUG: Available tile coordinates ===")
        for idx, item in enumerate(items):
            tile_x = item['json']['tileX']
            tile_z = item['json']['tileZ']
            print(f"Item {idx}: tileX={tile_x}, tileZ={tile_z}")

        for idx, item in enumerate(items):
            tile_x = item['json']['tileX']
            tile_z = item['json']['tileZ']

            # Collect pairedItem if present
            if 'pairedItem' in item:
                paired_items.append(item['pairedItem'])
            else:
                paired_items.append(None)

            if 'binary' in item and 'data' in item['binary']:
                image_data = item['binary']['data']['data']
                image_buffer = base64.b64decode(image_data)
                img = Image.open(io.BytesIO(image_buffer))
                tile_images[(tile_x, tile_z)] = img
            else:
                raise ValueError(f"No image data found for tile ({tile_x}, {tile_z})")

        if not tile_images:
            raise ValueError("No valid tile images found")

        print(f"=== DEBUG: Loaded {len(tile_images)} tiles ===")
        print(f"Available coordinates: {list(tile_images.keys())}")

        # Check what coordinates we actually have and adjust accordingly
        available_coords = list(tile_images.keys())

        # Try to determine the actual grid bounds
        min_x = min(coord[0] for coord in available_coords)
        max_x = max(coord[0] for coord in available_coords)
        min_z = min(coord[1] for coord in available_coords)
        max_z = max(coord[1] for coord in available_coords)

        print(f"Grid bounds: X from {min_x} to {max_x}, Z from {min_z} to {max_z}")

        # Build coordinate order based on actual available coordinates
        coordinate_order = []
        for z in range(min_z, max_z + 1):
            for x in range(min_x, max_x + 1):
                if (x, z) in tile_images:
                    coordinate_order.append((x, z))

        print(f"Coordinate order: {coordinate_order}")

        # Check if we have a complete grid
        expected_tiles = (max_x - min_x + 1) * (max_z - min_z + 1)
        if len(coordinate_order) != expected_tiles:
            print(f"WARNING: Expected {expected_tiles} tiles, but only have {len(coordinate_order)}")

        # If we don't have all tiles, use only available ones
        if len(coordinate_order) < 9:
            print("WARNING: Less than 9 tiles available, using available tiles only")

        # Determine grid dimensions
        grid_width = max_x - min_x + 1
        grid_height = max_z - min_z + 1

        images = [tile_images[coords] for coords in coordinate_order]
        img_width, img_height = images[0].size
        composite_width = img_width * grid_width
        composite_height = img_height * grid_height
        composite = Image.new('RGB', (composite_width, composite_height))

        # Paste images in grid
        for coords in coordinate_order:
            img = tile_images[coords]
            # Calculate position in grid
            col = coords[0] - min_x  # 0, 1, 2
            row = coords[1] - min_z  # 0, 1, 2

            x = col * img_width
            y = row * img_height
            composite.paste(img, (x, y))

        # Add grid lines
        draw = ImageDraw.Draw(composite)
        for i in range(1, grid_width):
            x = i * img_width
            draw.line([(x, 0), (x, composite_height)], fill="white", width=2)
        for i in range(1, grid_height):
            y = i * img_height
            draw.line([(0, y), (composite_width, y)], fill="white", width=2)

        # Add coordinate labels
        try:
            font = ImageFont.load_default()
            for coords in coordinate_order:
                col = coords[0] - min_x
                row = coords[1] - min_z
                x = col * img_width + 5
                y = row * img_height + 5
                label = f"({coords[0]},{coords[1]})"
                draw.text((x, y), label, fill="yellow", font=font)
        except:
            pass

        buffer = io.BytesIO()
        composite.save(buffer, format='PNG')
        buffer.seek(0)
        image_base64 = base64.b64encode(buffer.getvalue()).decode('utf-8')

        return [{
            'json': {
                'success': True,
                'grid_size': f'{grid_width}x{grid_height}',
                'available_coordinates': available_coords,
                'coordinate_mapping': {
                    f'tile_{coords[0]}_{coords[1]}': coords for coords in coordinate_order
                },
                'dimensions': {
                    'width': composite_width,
                    'height': composite_height
                }
            },
            'binary': {
                'data': {
                    'data': image_base64,
                    'mimeType': 'image/png',
                    'fileName': 'minecraft_world_view.png'
                }
            },
            'pairedItem': [ {'item': i} for i in range(len(items)) ]
        }]

    except Exception as e:
        return [{
            'json': {
                'success': False,
                'error': str(e),
                'debug_info': {
                    'available_coordinates': list(tile_images.keys()) if 'tile_images' in locals() else 'Not available',
                    'total_items': len(items)
                }
            }
        }]

return stitch_minecraft_tiles()

