const match = positionText.match(regex);

if (match) {
  const worldX = parseFloat(match[1]);
  const worldY = parseFloat(match[2]);
  const worldZ = parseFloat(match[3]);

  // Generate BlueMap tile path (based on your filesystem structure)
  const zoom = 0;           // Zoom level
  const tileSize = 512;     // BlueMap tile size at zoom 0
  const tileX = Math.floor(worldX / tileSize);
  const tileZ = Math.floor(worldZ / tileSize);

  // Build the correct BlueMap URL based on your structure
  const tileUrl = `http://minecraft-250712.kodelab.dev:8100/maps/world/tiles/${zoom}/x${tileX}/z${tileZ}.prbm.gz`;

  return {
    json: {
      worldX: worldX,
      worldY: worldY,
      worldZ: worldZ,
      tileX: tileX,
      tileZ: tileZ,
      zoom: zoom,
      tileUrl: tileUrl,
      tilePath: `${zoom}/x${tileX}/z${tileZ}.prbm.gz`
    }
  };
} else {
  return {
    json: {
      error: "Could not parse position",
      originalText: positionText
    }
  };
}
